"""Unified company/contact search and polished intelligence drill-down drawer."""
from __future__ import annotations


def install_sprint41_drilldown_ux(app):
    @app.after_request
    def enhance(response):
        if response.status_code != 200 or not response.is_sequence:
            return response
        try:
            from flask import request
            if request.path != "/platform/control-tower":
                return response
            html = response.get_data(as_text=True)
            if "s41-intelligence-drawer" in html or "</body>" not in html.lower():
                return response
            style = r'''<style id="s41-intelligence-drawer">
.s41-searchbar{position:relative;z-index:5;display:flex;gap:9px;margin:0 0 14px;padding:10px;border:1px solid #58d6ff30;border-radius:16px;background:#071a34cc;box-shadow:0 12px 35px #0004}.s41-searchbar input{flex:1;min-width:0;border:1px solid #ffffff16;border-radius:12px;background:#ffffff08;color:#eef6ff;padding:12px 14px;outline:none}.s41-searchbar input:focus{border-color:#58d6ff77;box-shadow:0 0 0 3px #58d6ff12}.s41-searchbar button{border:0;border-radius:12px;padding:0 16px;font-weight:800;background:linear-gradient(135deg,#58d6ff,#45e0a8);color:#05213a;cursor:pointer}.s41-hint{align-self:center;color:#718cac;font-size:10px;white-space:nowrap}.s41-results{position:absolute;left:10px;right:10px;top:64px;display:none;max-height:420px;overflow:auto;padding:8px;border:1px solid #58d6ff35;border-radius:15px;background:#07162df5;box-shadow:0 24px 65px #000b}.s41-results.show{display:grid;gap:6px}.s41-result{display:flex;justify-content:space-between;gap:12px;padding:11px;border-radius:11px;background:#ffffff06;border:1px solid transparent;cursor:pointer}.s41-result:hover{border-color:#58d6ff55;background:#ffffff0a}.s41-result b{font-size:12px}.s41-result p{margin:3px 0 0;color:#829bbb;font-size:11px}.s41-kind{font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:#58d6ff}.s41-drawer-backdrop{position:fixed;inset:0;z-index:10000;display:none;background:#020814b8;backdrop-filter:blur(7px)}.s41-drawer-backdrop.show{display:block}.s41-drawer{position:absolute;right:0;top:0;height:100%;width:min(560px,94vw);overflow:auto;padding:22px;background:radial-gradient(circle at 85% 0,#ff7a4521,transparent 35%),linear-gradient(160deg,#0b2040,#06152c);border-left:1px solid #58d6ff35;box-shadow:-30px 0 80px #000b;animation:s41drawer .25s ease-out}.s41-drawer-close{float:right;border:1px solid #ffffff1c;border-radius:10px;background:#ffffff08;color:white;padding:8px 11px;cursor:pointer}.s41-profile-head{display:flex;gap:14px;align-items:center;margin:24px 0 18px}.s41-avatar{width:58px;height:58px;border-radius:17px;display:grid;place-items:center;font-size:24px;background:linear-gradient(135deg,#58d6ff33,#ff7a4533);border:1px solid #ffffff18}.s41-profile-head h2{margin:0}.s41-profile-head p{margin:4px 0 0;color:#8fa8c8}.s41-score{margin-left:auto;min-width:64px;text-align:center;padding:10px;border-radius:14px;background:#45e0a813;border:1px solid #45e0a833}.s41-score strong{display:block;font-size:24px;color:#55e9b3}.s41-section{margin-top:12px;padding:15px;border:1px solid #ffffff12;border-radius:15px;background:#ffffff06}.s41-section h3{margin:0 0 10px;font-size:13px}.s41-field{display:grid;grid-template-columns:125px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid #ffffff0b}.s41-field:last-child{border:0}.s41-field span{color:#8099ba;font-size:11px}.s41-field b,.s41-field a{font-size:12px;color:#e6f1ff;overflow-wrap:anywhere}.s41-contact-row{padding:11px;border-radius:12px;background:#ffffff06;margin-top:7px;cursor:pointer;border:1px solid transparent}.s41-contact-row:hover{border-color:#58d6ff44}.s41-drawer-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.s41-drawer-actions button{border:0;border-radius:11px;padding:10px 13px;font-weight:800;cursor:pointer}.s41-approve{background:#45e0a8;color:#05271b}.s41-favorite{background:#ffb347;color:#2a1702}.s41-reject{background:#ff758b;color:#300712}@keyframes s41drawer{from{transform:translateX(30px);opacity:0}}
</style>'''
            shell = r'''<div class="s41-searchbar" id="s41SearchBar"><input id="s41GlobalSearch" placeholder="Search companies, contacts, states, cities, NMLS or email…" autocomplete="off"><button id="s41SearchButton">Search</button><span class="s41-hint">Press /</span><div class="s41-results" id="s41SearchResults"></div></div><div class="s41-drawer-backdrop" id="s41DrawerBackdrop"><aside class="s41-drawer" id="s41Drawer"><button class="s41-drawer-close" id="s41DrawerClose">Close</button><div id="s41DrawerBody"></div></aside></div>'''
            script = r'''<script id="s41-drilldown-script">
(function(){const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));let cache={contacts:[],companies:[]};
function field(k,v,link){if(v===null||v===undefined||v==='')return'';return `<div class="s41-field"><span>${esc(k)}</span>${link?`<a href="${esc(link)}" target="_blank" rel="noopener">${esc(v)}</a>`:`<b>${esc(v)}</b>`}</div>`}
function openDrawer(body){$('s41DrawerBody').innerHTML=body;$('s41DrawerBackdrop').classList.add('show')}
function closeDrawer(){$('s41DrawerBackdrop').classList.remove('show')}
async function openContact(id){openDrawer('<div class="s41-empty">Loading contact intelligence…</div>');try{const d=await api(`/api/platform/sprint38/contacts/${id}`);openDrawer(`<div class="s41-profile-head"><div class="s41-avatar">👤</div><div><h2>${esc(d.canonical_person_name||d.person_name||'Public contact')}</h2><p>${esc(d.role||'Mortgage professional')} · ${esc(d.canonical_company_name||d.company_name||'')}</p></div><div class="s41-score"><strong>${d.opportunity_score||0}</strong><small>score</small></div></div><div class="s41-section"><h3>Public business profile</h3>${field('Company',d.company_name)}${field('Location',[d.city,d.state].filter(Boolean).join(', '))}${field('Email',d.public_email,d.public_email?'mailto:'+d.public_email:'')}${field('Phone',d.phone,d.phone?'tel:'+d.phone:'')}${field('NMLS',d.nmls_id)}${field('Source',d.source_url,d.source_url)}</div><div class="s41-section"><h3>Ember recommendation</h3><p>${esc(d.next_best_action||'Review and verify this prospect.')}</p>${field('Confidence',d.ai_confidence||d.confidence)}${field('Product fit',d.product_fit)}${field('Review status',d.review_status)}</div><div class="s41-drawer-actions"><button class="s41-approve" onclick="s41Review(${d.id},'approve')">Approve</button><button class="s41-favorite" onclick="s41Review(${d.id},'favorite')">Favorite</button><button class="s41-reject" onclick="s41Review(${d.id},'reject')">Reject</button></div>`)}catch(e){openDrawer(`<div class="s41-empty">${esc(e.message||'Could not load contact')}</div>`)}}
async function openCompany(name){openDrawer('<div class="s41-empty">Loading company intelligence…</div>');try{const d=await api('/api/platform/sprint38/companies/detail?name='+encodeURIComponent(name)),c=d.company||{},rows=d.contacts||[];openDrawer(`<div class="s41-profile-head"><div class="s41-avatar">🏢</div><div><h2>${esc(c.company_name||name)}</h2><p>${esc([c.city,c.state].filter(Boolean).join(', '))}</p></div><div class="s41-score"><strong>${rows.length}</strong><small>contacts</small></div></div><div class="s41-section"><h3>Company profile</h3>${field('Location',[c.city,c.state].filter(Boolean).join(', '))}${field('Domain',c.source_domain)}${field('Website',c.source_url,c.source_url)}${field('Discovered',c.discovered_at)}</div><div class="s41-section"><h3>Discovered contacts</h3>${rows.length?rows.map(x=>`<div class="s41-contact-row" onclick="openContact(${x.id})"><b>${esc(x.person_name||'Company contact')}</b><p>${esc(x.role||'')} · Score ${x.opportunity_score||0} · ${esc(x.review_status||'')}</p></div>`).join(''):'<div class="s41-empty">No contacts discovered yet.</div>'}</div>`)}catch(e){openDrawer(`<div class="s41-empty">${esc(e.message||'Could not load company')}</div>`)}}
async function review(id,action){const r=await fetch(`/api/platform/sprint38/contacts/${id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Review failed');await openContact(id);if(window.loadS41)window.loadS41()}
async function ensureCache(){if(cache.contacts.length||cache.companies.length)return;const [c,p]=await Promise.all([api('/api/platform/sprint38/contacts?limit=500'),api('/api/platform/sprint38/companies?limit=500')]);cache.contacts=c.items||[];cache.companies=p.items||[]}
async function search(){const q=$('s41GlobalSearch').value.trim().toLowerCase(),box=$('s41SearchResults');if(!q){box.classList.remove('show');return}box.innerHTML='<div class="s41-empty">Searching intelligence…</div>';box.classList.add('show');try{await ensureCache();const contacts=cache.contacts.filter(x=>[x.person_name,x.company_name,x.role,x.state,x.city,x.public_email,x.phone,x.nmls_id].some(v=>String(v||'').toLowerCase().includes(q))).slice(0,8);const companies=cache.companies.filter(x=>[x.company_name,x.state,x.city,x.source_domain].some(v=>String(v||'').toLowerCase().includes(q))).slice(0,8);const results=[...contacts.map(x=>({kind:'Contact',title:x.person_name||'Public contact',sub:[x.company_name,x.role,x.state].filter(Boolean).join(' · '),click:`openContact(${x.id})`})),...companies.map(x=>({kind:'Company',title:x.company_name,sub:[x.city,x.state,`${x.contact_count||0} contacts`].filter(Boolean).join(' · '),click:`openCompany(${JSON.stringify(x.company_name)})`}))];box.innerHTML=results.length?results.map(x=>`<div class="s41-result" onclick='${x.click}'><div><b>${esc(x.title)}</b><p>${esc(x.sub)}</p></div><span class="s41-kind">${x.kind}</span></div>`).join(''):'<div class="s41-empty">No matching intelligence yet.</div>'}catch(e){box.innerHTML=`<div class="s41-empty">${esc(e.message||'Search unavailable')}</div>`}}
window.openContact=openContact;window.openCompany=openCompany;window.s41Review=review;document.addEventListener('DOMContentLoaded',()=>{const command=$('s41Command');if(command)command.insertAdjacentHTML('afterend',`__SHELL__`);else(document.querySelector('main')||document.body).insertAdjacentHTML('afterbegin',`__SHELL__`);$('s41SearchButton').onclick=search;$('s41GlobalSearch').addEventListener('input',()=>{clearTimeout(window.s41SearchTimer);window.s41SearchTimer=setTimeout(search,180)});$('s41GlobalSearch').addEventListener('keydown',e=>{if(e.key==='Enter')search()});$('s41DrawerClose').onclick=closeDrawer;$('s41DrawerBackdrop').onclick=e=>{if(e.target===$('s41DrawerBackdrop'))closeDrawer()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!/input|textarea/i.test(document.activeElement.tagName)){e.preventDefault();$('s41GlobalSearch').focus()}if(e.key==='Escape'){closeDrawer();$('s41SearchResults').classList.remove('show')}})});})();
</script>'''.replace('__SHELL__',shell.replace('`','\\`'))
            html=html.replace('</head>',style+'</head>')
            pos=html.lower().rfind('</body>');html=html[:pos]+script+html[pos:]
            response.set_data(html);response.headers['Content-Length']=str(len(response.get_data()))
        except Exception:
            app.logger.exception('Sprint 41 intelligence drilldown enhancement failed')
        return response
    return app
